css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .cuenta-fila{display: grid; grid-template-columns: 1fr 75px; gap: 10px; padding: 4px 9px; border: 1.2px solid var(--bosque); border-radius: 6px; margin-bottom: 4px; align-items: center;}
.mz .cuenta-dibujos{font-size: 16px; font-weight: 500;}
.mz .cuenta-caja{border: 1.5px solid var(--bosque); border-radius: 6px; height: 30px;}
.mz .unir-tabla{display: grid; grid-template-columns: 100px 1fr 170px; gap: 4px; margin-bottom: 3px; align-items: center;}
.mz .unir-num{font-size: 19px; font-weight: 700; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 4px 0;}
.mz .unir-palabra{font-size: 13.5px; font-weight: 500; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 6px 0;}
.mz .serie-cajas{display: flex; gap: 4px; flex-wrap: nowrap; font-size: 16px; font-weight: 700;}
.mz .serie-cajas .caja-num{width: 50px; height: 38px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center; flex-shrink: 0;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .entre-fila{display: flex; gap: 8px; align-items: center; margin-bottom: 5px; font-size: 17px; font-weight: 700;}
.mz .entre-fila .caja-num{width: 42px; height: 40px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center;}
.mz .entre-fila .caja-num.vacia{background: #fff;}
